import{prepareCompletedUnclaimedJungleReview}from'./exhibit-qa-ready.mjs';
import{prepareJungleMainSession}from'./session-owner.mjs';
import{SpeciesCatalogService}from'../../../species-catalog-service.mjs';
import{createCanonicalCreature,canonicalHp}from'../../../canonical-session.mjs';
export const PROLOGUE_PAIR_QA_BANNER='저레벨 원래 패배 준비 QA · 일반 난이도 아님 · 사용자 저장 0';
let preparationUsed=false;
export async function prepareProloguePairQAStorage({adapter,initialRuntime,signal,search}={}){
 if(import.meta.env?.DEV!==true||typeof search!=='string')throw Error('PROLOGUE_PAIR_QA_DEV_ONLY');const q=new URLSearchParams(search);if(q.getAll('jungleNative').length!==1||q.get('jungleNative')!=='1'||q.getAll('jungleQAReady').length!==1||q.get('jungleQAReady')!=='1'||q.getAll('prologuePairQAReady').length!==1||q.get('prologuePairQAReady')!=='1'||q.has('jungleExhibitQAReady'))throw Error('PROLOGUE_PAIR_QA_QUERY_REJECTED');if(preparationUsed)throw Error('PROLOGUE_PAIR_QA_ALREADY_USED');preparationUsed=true;
 const check=()=>{if(signal?.aborted)throw Object.assign(Error('QA_PREPARATION_ABORTED'),{code:'QA_PREPARATION_ABORTED'})};check();const tick=async()=>{await new Promise(r=>setTimeout(r,0));check()};
 const catalog=new SpeciesCatalogService({namespace:'canonical',adapter}),initial=structuredClone(initialRuntime),starter=createCanonicalCreature(catalog,initial.starterId,1);if(starter.hp!==canonicalHp(catalog,starter.speciesId,1))throw Error('QA_INITIAL_FULL_HP_REQUIRED');initial.party=[starter];const initialHP=starter.hp;
 const prepared=await prepareCompletedUnclaimedJungleReview({adapter,initialRuntime:initial,signal});check();let owner,battles=0,turns=0;
 const driver=async battle=>{if(++battles!==1)throw Error('QA_ONE_ORIGINAL_BATTLE_ONLY');for(;turns<128;turns++){await tick();const s=battle.snapshot();if(s.phase==='ended')return s;if(s.phase==='forced-switch'){const index=s.party.findIndex(m=>m.hp>0);if(index<0)throw Error('QA_BATTLE_SWITCH_STATE');battle.act({type:'switch',index});continue}const mon=s.party[s.active];battle.act({type:'move',moveId:mon.moves.find(m=>m.pp>0)?.id??'SYSTEM_STRUGGLE'})}throw Error('QA_BATTLE_TURN_BOUND');};
 try{owner=await prepareJungleMainSession({featureGate:'S5_JUNGLE_PAIR_MEMORY_REVIEW_ONLY',storage:prepared.storage,adapter,restore:true,signal});check();const world=owner.bindWorld({hooks:{dialogue:async()=>{check()}},battleDriver:driver,rng:()=>.4});
 const to=async(x,y)=>{check();let f=owner.snapshot().state.foot;if(f[0]!==x&&f[1]!==y)throw Error('QA_NON_AXIS_ROUTE');while(f[0]!==x||f[1]!==y){await tick();const dx=Math.sign(x-f[0])*Math.min(240,Math.abs(x-f[0])),dy=Math.sign(y-f[1])*Math.min(240,Math.abs(y-f[1]));if(owner.move(dx,dy)!==Math.abs(dx||dy))throw Error('QA_NATIVE_WALK_BLOCKED');f=owner.snapshot().state.foot}};
 await to(4084,187);await owner.complete();check();for(const[x,y]of[[4084,494],[480,494],[480,568],[125,568]])await to(x,y);owner.move(-1,0);owner.release();if(!owner.interact().ok)throw Error('QA_INTERIOR_EXIT');owner.release();await to(768,1004);await owner.returnToHub();for(const[x,y]of[[770,1065],[770,630],[3138,630],[3138,536]])await to(x,y);owner.move(100,0);owner.release();const result=await owner.challengeHarin();check();const state=owner.snapshot(),runtime=world.snapshot();if(result.completed!==false||battles!==1||runtime.position.scene!=='world:hub:PROLOGUE'||state.state.foot[0]!==945||state.state.foot[1]!==560||runtime.progress.completedEvents.includes('RIVAL_03')||!state.puzzle.cOpen||runtime.progress.items.plant_scan_module!==1||runtime.economy?.recovery?.hubId!=='CENTER:PROLOGUE')throw Error('QA_ORIGINAL_LOSS_POSTCONDITION');owner.save();check();return Object.freeze({storage:prepared.storage,report:Object.freeze({banner:PROLOGUE_PAIR_QA_BANNER,initialPartyFixture:Object.freeze({speciesId:starter.speciesId,level:1,hp:initialHP,maximumHP:initialHP,partySize:1}),battles,turns,originalOutcome:'lost',originalRecoveryHub:'CENTER:PROLOGUE',preparedFoot:Object.freeze([945,560]),ordinaryDifficulty:false,userStorageWrites:0,flagsOrPositionInjected:false,battleDriverReturned:false})});
 }finally{owner?.dispose()}
}
